function validate([paths]) {
  if (!Array.isArray(paths) || paths.length < 1 || paths.length > 20000) return 'paths needs 1 to 20000 folders.';
  const seen = new Set();
  let letters = 0;
  for (const path of paths) {
    if (!Array.isArray(path) || path.length < 1 || path.length > 500) return 'Each path has 1 to 500 names.';
    for (const name of path) {
      if (typeof name !== 'string' || !/^[a-z]{1,10}$/.test(name)) return 'Each name is 1 to 10 lowercase letters.';
      letters += name.length;
    }
    const key = path.join('/');
    if (seen.has(key)) return 'No folder may be listed twice.';
    seen.add(key);
  }
  if (letters > 200000) return 'The names may hold at most 200000 letters in total.';
  for (const path of paths) {
    if (path.length > 1 && !seen.has(path.slice(0, -1).join('/'))) return 'Every folder needs its parent folder listed.';
  }
  return null;
}

