function deleteDuplicateFolder(paths) {
  const root = { children: new Map(), key: '' };
  for (const path of paths) {
    let node = root;
    for (const name of path) {
      if (!node.children.has(name)) {
        node.children.set(name, { children: new Map(), key: '' });
      }
      node = node.children.get(name);
    }
  }

  const counts = new Map();
  const serialize = (node) => {
    if (node.children.size === 0) return '';
    const parts = [];
    for (const [name, child] of node.children) {
      parts.push(name + '(' + serialize(child) + ')');
    }
    parts.sort();
    node.key = parts.join('');
    counts.set(node.key, (counts.get(node.key) || 0) + 1);
    return node.key;
  };
  serialize(root);

  const result = [];
  const current = [];
  const collect = (node) => {
    for (const [name, child] of node.children) {
      if (child.key !== '' && counts.get(child.key) > 1) continue;
      current.push(name);
      result.push([...current]);
      collect(child);
      current.pop();
    }
  };
  collect(root);
  return result;
}

