function deleteDuplicateFolder(paths) {
  // Build the tree, then compare every pair of non-empty folders directly, with no hashing.
  const top = new Map();
  const folders = [];
  for (const p of paths) {
    let at = top;
    for (const nm of p) {
      if (!at.has(nm)) at.set(nm, new Map());
      at = at.get(nm);
    }
    folders.push({ p, at });
  }
  const same = (x, y) => {
    const kx = [...x.keys()].sort(), ky = [...y.keys()].sort();
    if (kx.join('/') !== ky.join('/')) return false;
    return kx.every(k => same(x.get(k), y.get(k)));
  };
  const marked = new Set();
  for (const f of folders) {
    if (f.at.size === 0) continue;
    if (folders.some(g => g !== f && g.at.size > 0 && same(f.at, g.at))) marked.add(f.p.join('/'));
  }
  return paths.filter(p => p.every((_, i) => !marked.has(p.slice(0, i + 1).join('/'))));
}

