function generate(rand, size) {
  const large = size === 'large';
  const target = large ? 1500 + Math.floor(rand() * 500) : (rand() < 0.15 ? 1 : 3 + Math.floor(rand() * 9));
  const maxDepth = large ? 9 : 4;
  const pool = large ? ['a', 'b', 'c', 'd', 'e', 'f', 'xy', 'docs', 'src', 'tmp'] : (rand() < 0.5 ? ['a', 'b'] : ['a', 'b', 'c']);
  const pick = list => list[Math.floor(rand() * list.length)];
  const root = { children: new Map(), depth: 0 };
  const nodes = [root];
  let count = 0;
  const add = (parent, name) => {
    const child = { children: new Map(), depth: parent.depth + 1 };
    parent.children.set(name, child);
    nodes.push(child);
    count++;
    return child;
  };
  const snapshot = node => [...node.children].map(([name, child]) => [name, snapshot(child)]);
  const height = plain => plain.reduce((h, [, sub]) => Math.max(h, 1 + height(sub)), 0);
  const sizeOf = plain => plain.reduce((s, [, sub]) => s + 1 + sizeOf(sub), 0);
  const plant = (parent, plain) => { for (const [name, sub] of plain) plant(add(parent, name), sub); };
  let guard = 0;
  while (count < target && guard++ < 100000) {
    const parent = pick(nodes);
    const free = pool.filter(name => !parent.children.has(name));
    if (!free.length || parent.depth >= maxDepth) continue;
    // Often copy an existing folder's contents somewhere else, so identical folders are common.
    if (rand() < (large ? 0.35 : 0.7)) {
      const source = pick(nodes);
      const plain = snapshot(source);
      if (plain.length && parent.depth + 1 + height(plain) <= maxDepth && count + 1 + sizeOf(plain) <= target + (large ? 0 : 4)) {
        plant(add(parent, pick(free)), plain);
        continue;
      }
    }
    add(parent, pick(free));
  }
  const paths = [];
  const walk = (node, trail) => {
    for (const [name, child] of node.children) {
      paths.push([...trail, name]);
      walk(child, [...trail, name]);
    }
  };
  walk(root, []);
  for (let i = paths.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [paths[i], paths[j]] = [paths[j], paths[i]];
  }
  return [paths];
}
